n = int(input("Enter a positive integer: "))

if n < 2:
    print(f"{n} is neither Prime nor Composite.")
else:
    for d in range(2, int(n ** 0.5) + 1):
        if n % d == 0:
            print(f"{n} is Composite (divisible by {d}).")
            break
    else:
        print(f"✨ {n} is a PRIME number!")

