# CBSE Class 12 - 3-Mark Stack Question Pattern (LIFO)
stack = []

books_catalog = {
    "Python Crash Course": 650,
    "NCERT Computer Science": 240,
    "Deep Learning with Python": 890,
    "SQL Pocket Guide": 380,
    "Algorithms Unlocked": 550
}

def PushBook(stk, catalog):
    """Pushes names of books costing more than ₹500 onto the stack."""
    for title, price in catalog.items():
        if price > 500:
            stk.append(title)
            print(f"PUSH -> '{title}' (₹{price})")

def PopBook(stk):
    """Pops and displays all elements from stack until Underflow."""
    print("\n--- Popping Stack (LIFO Order) ---")
    while True:
        if len(stk) == 0:
            print("Stack Empty (Underflow)")
            break
        print("POP  <-", stk.pop())

PushBook(stack, books_catalog)
PopBook(stack)

