# CBSE Class 12 Practical #4: Binary File Search & Update with pickle
import pickle

records = [
    {"roll": 1, "name": "Aarav", "marks": 82},
    {"roll": 2, "name": "Bhavya", "marks": 91},
    {"roll": 3, "name": "Chirag", "marks": 76}
]

with open("marks.dat", "wb") as f:
    for r in records:
        pickle.dump(r, f)

target_roll = int(input("Enter Roll No to update marks (1, 2, or 3): "))
new_marks = int(input("Enter new marks: "))

updated_list = []
found = False

with open("marks.dat", "rb") as f:
    try:
        while True:
            rec = pickle.load(f)
            if rec["roll"] == target_roll:
                rec["marks"] = new_marks
                found = True
            updated_list.append(rec)
    except EOFError:
        pass

if found:
    with open("marks.dat", "wb") as f:
        for r in updated_list:
            pickle.dump(r, f)
    print(f"\n✅ Successfully updated Roll No {target_roll}!")
else:
    print(f"\n❌ Roll No {target_roll} not found.")

print("\n📋 Current Binary File Contents:")
with open("marks.dat", "rb") as f:
    try:
        while True:
            print(" ", pickle.load(f))
    except EOFError:
        pass

